import math
from itertools import product

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a*b) // gcd(a, b)

def gcd_list(lst):
    if not lst:
        return 0
    result = lst[0]
    for i in range(1, len(lst)):
        result = gcd(result, lst[i])
    return result

def lcm_list(lst):
    if not lst:
        return 1 # LCM of an empty set is conventionally 1 in some contexts, but here we deal with positive integers.
    result = lst[0]
    for i in range(1, len(lst)):
        result = lcm(result, lst[i])
    return result

def count_good_partitions(sequence):
    n = len(sequence)
    count = 0
    for k in range(1, n):
        A_k = sequence[:k]
        B_k = sequence[k:]

        lcm_A = lcm_list(A_k)
        gcd_B = gcd_list(B_k)

        if lcm_A == gcd_B:
            count += 1
    return count

# --- Brute Force Search ---

# N=2
print("--- N=2 ---")
# Sequences (a1, a2) with 1 <= a1 < a2 < 10
n2_counts = {}
for a1 in range(1, 10):
    for a2 in range(a1 + 1, 10):
        seq = (a1, a2)
        count = count_good_partitions(seq)
        n2_counts[seq] = count
        if count > 0:
            print(f"Sequence {seq}: {count} good partitions.")

# N=3
print("\n--- N=3 ---")
# Sequences (a1, a2, a3) with 1 <= a1 < a2 < a3 < 10
n3_counts = {}
for a1 in range(1, 10):
    for a2 in range(a1 + 1, 10):
        for a3 in range(a2 + 1, 10):
            seq = (a1, a2, a3)
            count = count_good_partitions(seq)
            n3_counts[seq] = count
            if count > 0:
                print(f"Sequence {seq}: {count} good partitions.")

# N=4
print("\n--- N=4 ---")
# Sequences (a1, a2, a3, a4) with 1 <= a1 < a2 < a3 < a4 < 10
n4_counts = {}
for a1 in range(1, 10):
    for a2 in range(a1 + 1, 10):
        for a3 in range(a2 + 1, 10):
            for a4 in range(a3 + 1, 10):
                seq = (a1, a2, a3, a4)
                count = count_good_partitions(seq)
                n4_counts[seq] = count
                if count > 0:
                    print(f"Sequence {seq}: {count} good partitions.")

# Summarize findings
print("\n--- Summary ---")
print(f"N=2 findings: {len([c for c in n2_counts.values() if c > 0])} sequences found with >0 partitions (should be 0).")
print(f"N=3 findings: {len([c for c in n3_counts.values() if c > 0])} sequences found with >0 partitions.")
print(f"N=4 findings: {len([c for c in n4_counts.values() if c > 0])} sequences found with >0 partitions.")
